{{(() => {
  const ratings = [
    Rating29.value,
		Rating30.value,
		Rating31.value,
		Rating32.value,
    Rating33.value,
		Rating34.value,
		Rating35.value,
		Rating36.value
  ];

  const hasInvalidRating = ratings.some(r => r === null || r === 0);

  if (hasInvalidRating) {
    return "OBIETTIVO DELLA SETTIMANA: CAPACITÀ DI LAVORARE CON COLLEGHE E INTRODUZIONE AL COMPRO ORO";
  }

  const somma = ratings.reduce((acc, val) => acc + val, 0);

  return somma === 0 ? "" : (somma >= 20 ? "OBIETTIVO DELLA SETTIMANA RAGGIUNTO: CAPACITÀ DI LAVORARE CON COLLEGHE E INTRODUZIONE AL COMPRO ORO" : "OBIETTIVO DELLA SETTIMANA NON RAGGIUNTO: CAPACITÀ DI LAVORARE CON COLLEGHE E INTRODUZIONE AL COMPRO ORO");
})()
}}

